def max_vertical_run(grid, color):
    """Find max vertical run of given color in each column"""
    runs = []
    for c in range(min(21, len(grid[0]))):
        max_run = 0
        r = 0
        while r < len(grid):
            run_len = 0
            while r < len(grid) and grid[r][c] == color:
                run_len += 1
                r += 1
            max_run = max(max_run, run_len)
        if max_run > 0:
            runs.append(c)
    return runs

def max_any_vertical_run(grid):
    """For each column, find the column and colors that have max vertical runs"""
    col_max_runs = {}
    for c in range(min(21, len(grid[0]))):
        col_max_run = 0
        colors_with_max = []
        for color in set(val for row in grid for val in row):
            max_len = 0
            r = 0
            while r < len(grid):
                run_len = 0
                while r < len(grid) and grid[r][c] == color:
                    run_len += 1
                    r += 1
                max_len = max(max_len, run_len)
            if max_len >= col_max_run:
                if max_len > col_max_run:
                    col_max_run = max_len
                    colors_with_max = [color]
                else:
                    colors_with_max.append(color)
        col_max_runs[c] = (col_max_run, colors_with_max)
    return col_max_runs

